import { defineConfig } from 'vite';

// env-resources：构建与开发服务器配置（无业务逻辑）。
// 纯本地离线运行：相对 base 便于以静态文件方式托管 dist 产物。
export default defineConfig({
  base: './',
  server: {
    port: 5173,
    open: false,
  },
  preview: {
    port: 4173,
  },
  build: {
    target: 'es2022',
    outDir: 'dist',
    emptyOutDir: true,
    sourcemap: false,
  },
});

